/* Read-only preflight: no volume, route, DND or lock settings are changed. */
import android.app.KeyguardManager;
import android.app.NotificationManager;
import android.media.AudioManager;
import android.media.AudioDeviceInfo;
import android.os.PowerManager;
import android.os.Build;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
pm = context.getSystemService("power");
km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked())
    throw new JavaCodeException("Turn on and unlock the phone before controlling Signia");
am = context.getSystemService("audio");
nm = context.getSystemService("notification");
streamName = tasker.getVariable("SIG3_AudioStream");
if (!"media".equals(streamName) && !"ring".equals(streamName))
    throw new JavaCodeException("Set SIG3_AudioStream to Signia's selected media or ring stream");
stream = "ring".equals(streamName) ? AudioManager.STREAM_RING : AudioManager.STREAM_MUSIC;
volume = am.getStreamVolume(stream);
maximum = am.getStreamMaxVolume(stream);
mode = am.getMode();
ringer = am.getRingerMode();
minimumText = tasker.getVariable("SIG3_MinAudioPercent");
minimumPercent = 50;
if (minimumText != null && !minimumText.equals("") && !minimumText.startsWith("%")) {
    if (!minimumText.matches("[0-9]{1,3}"))
        throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
    minimumPercent = Integer.parseInt(minimumText);
}
if (minimumPercent < 1 || minimumPercent > 100)
    throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
required = (maximum * minimumPercent + 99) / 100;
filter = nm.getCurrentInterruptionFilter();
outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS);
route = "";
external = false;
for (device : outputs) {
    type = device.getType();
    route = route + type + ":" + device.getProductName() + ";";
    /* Known connected external outputs; presence is conservative, not an active-route claim. */
    if (type == 3 || type == 4 || type == 7 || type == 8 || type == 11 || type == 12 || type == 22 || type == 23 || type == 26 || type == 27)
        external = true;
}
tasker.setVariable("SIG3_AudioDiagnostics", "stream=" + streamName + " volume=" + volume + "/" + maximum + "; minimum=" + required + "/" + maximum + "; ringerMode=" + ringer + "; mode=" + mode + "; interruptionFilter=" + filter + "; outputs=" + route);
/* BEGIN AUDIO POLICY: also exercised without Android by the policy test. */
if (filter != NotificationManager.INTERRUPTION_FILTER_ALL)
    throw new JavaCodeException("Turn off Do Not Disturb (including bedtime/night mode), then retry the Signia command");
if (ringer == AudioManager.RINGER_MODE_SILENT || ("ring".equals(streamName) && ringer != AudioManager.RINGER_MODE_NORMAL))
    throw new JavaCodeException("Unmute the phone; for Ring sound, also turn off vibrate-only mode, then retry");
if (maximum <= 0 || volume < required)
    throw new JavaCodeException("Raise phone " + streamName + " volume with the phone volume slider to at least " + required + "/" + maximum + " (" + minimumPercent + "% minimum), then retry");
/* END AUDIO POLICY */
if (mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION)
    throw new JavaCodeException("Phone call or communication audio is active");
if (external) throw new JavaCodeException("Disconnect external audio outputs before acoustic control");
return "ready";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Read-only live UI guard. Defaults are APK-derived and must be confirmed on the phone. */
import android.graphics.Rect;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
info = service.getServiceInfo();
if (info == null) throw new JavaCodeException("Tasker accessibility information unavailable");
info.flags = info.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;
service.setServiceInfo(info);
root = service.getRootInActiveWindow();
if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
    throw new JavaCodeException("Signia is not the active accessibility window");
family = tasker.getVariable("SIG3_Family");
controlId = tasker.getVariable("SIG3_" + family + "ControlId");
programId = tasker.getVariable("SIG3_ProgramId");
if (controlId == null || programId == null)
    throw new JavaCodeException("Configure the common control ID and current program ID");
// Walk the actual tree: this phone returns no matches from direct ID lookup.
queue = new java.util.ArrayList(); queue.add(root);
visible = 0; count = 0; program = null; control = null; headerCount = 0; headerProgram = null;
for (scan = 0; scan < queue.size() && scan < 300; scan++) {
    node = (AccessibilityNodeInfo) queue.get(scan);
    nodeId = node.getViewIdResourceName();
    description = node.getContentDescription();
    if (node.isVisibleToUser() && description != null) {
        header = description.toString();
        if (header.startsWith("Hearing program ") && header.endsWith(" Active")) {
            name = header.substring("Hearing program ".length(), header.length() - " Active".length()).trim();
            if (name.length() > 0) { headerProgram = name; headerCount++; }
        }
    }
    if (controlId.equals(nodeId) && node.isVisibleToUser() && node.isEnabled()) { visible++; control = node; }
    if (programId.equals(nodeId) && node.isVisibleToUser()) {
        value = node.getText();
        if (value == null || value.toString().trim().length() == 0) value = node.getContentDescription();
        if (value != null && value.toString().trim().length() > 0) {
            program = value.toString().trim(); count++;
        }
    }
    for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
        child = node.getChild(childIndex);
        if (child != null) queue.add(child);
    }
}
if (visible == 0 && "Tinnitus".equals(family)) throw new JavaCodeException("Tinnitus unavailable for this program");
if (visible != 1) throw new JavaCodeException("Expected exactly one enabled " + family + " common control: " + controlId);
// Signia changes the label ID with the program (Universal, TV, etc.).
// The actual visible accessibility header is stable across those programs.
if (count == 0 && headerCount == 1) { program = headerProgram; count = 1; }
if (count != 1 || headerCount > 1) throw new JavaCodeException("Cannot identify current program unambiguously");
if (headerCount == 1 && !headerProgram.equals(program)) throw new JavaCodeException("Program label and active header disagree");
savedProgram = tasker.getVariable("SIG3_SettingsExpectedProgram");
if (savedProgram != null && savedProgram.length() > 0 && !savedProgram.startsWith("%") && !savedProgram.equals(program))
    throw new JavaCodeException("Program changed during settings operation; saved program=" + savedProgram + "; current=" + program);
baseline = tasker.getVariable("SIG3_Program");
if (baseline != null && !baseline.equals(program))
    throw new JavaCodeException("Program changed during operation: " + baseline + " -> " + program);
tasker.setVariable("SIG3_Program", program);
tasker.setVariable("SIG3_UIControl", controlId);
// The numeric label's accessibility bounds extend to the bottom of the track.
// Position the gesture from native progress and explicitly calibrated track endpoints.
topText = tasker.getVariable("SIG3_" + family + "TrackTopY");
bottomText = tasker.getVariable("SIG3_" + family + "TrackBottomY");
if (topText != null && bottomText != null) {
    rect = new Rect(); control.getBoundsInScreen(rect);
    expectedBounds = tasker.getVariable("SIG3_" + family + "TrackBounds");
    actualBounds = rect.left + "," + rect.top + "," + rect.right + "," + rect.bottom;
    if (!actualBounds.equals(expectedBounds)) throw new JavaCodeException("Slider bounds changed; recalibrate track endpoints");
    top = Float.parseFloat(topText); bottom = Float.parseFloat(bottomText);
    range = control.getRangeInfo();
    if (range == null || range.getMax() <= range.getMin() || top < rect.top || bottom > rect.bottom || bottom <= top)
        throw new JavaCodeException("Invalid slider position calibration");
    fraction = (range.getCurrent() - range.getMin()) / (range.getMax() - range.getMin());
    if (Float.isNaN(fraction) || fraction < 0 || fraction > 1) throw new JavaCodeException("Invalid current native progress");
    tasker.setVariable("SIG3_" + family + "X", "" + rect.centerX());
    tasker.setVariable("SIG3_" + family + "Y", "" + Math.round(bottom - fraction * (bottom - top)));
}
return "verified";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Tasker 6.6.20 Java Code (BeanShell). No root, ADB or helper app. */
import android.accessibilityservice.AccessibilityService;
import android.accessibilityservice.GestureDescription;
import android.graphics.Path;
import android.os.Build;
import android.os.Handler;
import android.os.Looper;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicReference;
import com.joaomgcd.taskerm.action.java.ClassImplementation;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Wait for Android's actual completion/cancellation, not merely acceptance. */
performStroke(service, stroke, phase) {
    signal = new CountDownLatch(1);
    result = new AtomicReference("timeout");
    callback = tasker.implementClass(AccessibilityService.GestureResultCallback.class,
        new ClassImplementation() {
            run(Callable superCaller, String methodName, Object[] args) {
                if (methodName.equals("onCompleted")) {
                    result.set("completed");
                    signal.countDown();
                    return null;
                }
                if (methodName.equals("onCancelled")) {
                    result.set("cancelled");
                    signal.countDown();
                    return null;
                }
                return superCaller.call();
            }
        });
    tasker.setVariable("SIG3_TouchStage", phase);
    builder = new GestureDescription.Builder();
    if (phase.equals("move") && direct && "Tinnitus".equals(family)
        && Integer.parseInt(tasker.getVariable("sig3_start")) == 0) {
        tapPath = new Path(); tapPath.moveTo(x, y);
        builder.addStroke(new GestureDescription.StrokeDescription(tapPath, 0, 50, false));
    }
    gesture = builder.addStroke(stroke).build();
    if (!service.dispatchGesture(gesture, callback, new Handler(Looper.getMainLooper())))
        throw new JavaCodeException(phase + ": dispatchGesture rejected");
    if (!signal.await(3, TimeUnit.SECONDS))
        throw new JavaCodeException(phase + ": completion timed out after 3000 ms");
    if (!result.get().equals("completed"))
        throw new JavaCodeException(phase + ": Android cancelled gesture");
}


try {
if (Build.VERSION.SDK_INT < 26)
    throw new JavaCodeException("Slider gesture requires Android 8 or later");
service = tasker.getAccessibilityService();
if (service == null)
    throw new JavaCodeException("Enable Tasker in Android Settings > Accessibility > Installed apps");
x = Float.parseFloat(tasker.getVariable("sig3_x"));
y = Float.parseFloat(tasker.getVariable("sig3_y"));
endY = Float.parseFloat(tasker.getVariable("sig3_end_y"));
direct = "1".equals(tasker.getVariable("sig3_drag_direct"));
family = tasker.getVariable("SIG3_Family");
if (direct) {
    if (!"Volume".equals(family) && !"Balance".equals(family) && !"Tinnitus".equals(family))
        throw new JavaCodeException("Unknown direct slider family");
    top = Float.parseFloat(tasker.getVariable("SIG3_" + family + "TrackTopY"));
    bottom = Float.parseFloat(tasker.getVariable("SIG3_" + family + "TrackBottomY"));
    target = Integer.parseInt(tasker.getVariable("sig3_target"));
    minimum = "Balance".equals(family) ? -8 : 0;
    maximum = minimum + 15;
    x = Float.parseFloat(tasker.getVariable("SIG3_" + family + "X"));
    y = Float.parseFloat(tasker.getVariable("SIG3_" + family + "Y"));
    if (Float.isNaN(top) || Float.isNaN(bottom) || top < 0 || bottom <= top
        || target < minimum || target > maximum || y < top || y > bottom)
        throw new JavaCodeException("Invalid calibrated direct " + family + " track");
    endY = Math.round(bottom - (target - minimum) * (bottom - top) / 15.0f);
    tasker.setVariable("sig3_x", "" + x);
    tasker.setVariable("sig3_y", "" + y);
    tasker.setVariable("sig3_end_y", "" + endY);
}
if (Float.isNaN(x) || Float.isNaN(y) || Float.isNaN(endY)
    || x < 0 || endY < 0 || Math.abs(y - endY) < 1 || (!direct && Math.abs(y - endY) > 200))
    throw new JavaCodeException("Invalid calibrated step coordinates");
metrics = service.getResources().getDisplayMetrics();
if (x >= metrics.widthPixels || y < 0 || y >= metrics.heightPixels || endY >= metrics.heightPixels)
    throw new JavaCodeException("Gesture coordinates outside display bounds");
tasker.setVariable("SIG3_Gesture", tasker.getVariable("SIG3_Gesture") + "; actual path=" + x + "," + y + " -> " + x + "," + endY);
minimumTap = direct && "Tinnitus".equals(family) && Integer.parseInt(tasker.getVariable("sig3_start")) == 0;
if (minimumTap) tasker.setVariable("SIG3_Gesture", tasker.getVariable("SIG3_Gesture") + "; minimum tap released");
movePath = new Path();
movePath.moveTo(x, y);
movePath.lineTo(x, endY);
// One continuous DOWN-MOVE-UP stroke, matching the successful 650 ms USB drags.
moveStroke = new GestureDescription.StrokeDescription(movePath, minimumTap ? 200 : 0, 650, false);
performStroke(service, moveStroke, "move");
tasker.setVariable("SIG3_TouchStage", "released");
return "completed";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

